export type CriticReasonCode = 'critic_off' | 'no_review_model' | 'level_l1' | 'level_l2' | 'not_triggered' | 'no_evidence' | 'first_round_invalid' | 'second_round_invalid' | 'chain_invalid' | 'review_error';

